installer-gui-script.script:
function check_os() {
  if (system.compareVersions(system.version.ProductVersion, 'MIN_MACOS') < 0) {
    my.result.type = 'Fatal';
    my.result.title = 'macOS MIN_MACOS or later is required';
    my.result.message = 'ShapeWorks requires macOS MIN_MACOS or later. This Mac is running macOS ' +
      system.version.ProductVersion + '.';
    return false;
  }
  return true;
}
